// 全国简化容差最高 0.10°，口岸附近单独保留河道和岸线。
// 深港界线取自香港特别行政区政府民政事务总署《地方行政区分界》2026-09-11，简化容差 0.00045°。
// https://data.gov.hk/en-data/dataset/hk-had-json1-hong-kong-administrative-boundaries
// 政府开放数据使用条款 https://data.gov.hk/en/terms-and-conditions
// 珠江口岸线、澳门、厦门及金马轮廓取自 © OpenStreetMap contributors（2026-11-22 取样）。
// OSM 衍生顶点按 ODbL 1.0 提供，所取珠江口 OSM 岸段简化容差最高 0.00125°。https://www.openstreetmap.org/copyright
import CoreLocation
import Foundation

enum ChinaCoordinate: Sendable {
    private typealias Polygon = [(lon: Double, lat: Double)]

    static func isInMainland(latitude: Double, longitude: Double) -> Bool {
        guard inBounds(latitude: latitude, longitude: longitude) else { return false }
        return (contains(mainland, latitude: latitude, longitude: longitude)
                || contains(hainan, latitude: latitude, longitude: longitude)
                || coastalIslands.contains { contains($0, latitude: latitude, longitude: longitude) })
            && !isExcludedRegion(latitude: latitude, longitude: longitude)
    }

    // 边界两侧可能产生同一地图坐标，优先保留港澳台原值；大陆东岸加偏落入近海时回推确认。
    static func mapToGPS(_ coordinate: CLLocationCoordinate2D) -> WGS84Coordinate? {
        if isInMainland(latitude: coordinate.latitude, longitude: coordinate.longitude) {
            return gcjToWgs(coordinate)
        }
        if inBounds(latitude: coordinate.latitude, longitude: coordinate.longitude),
           !isExcludedRegion(latitude: coordinate.latitude, longitude: coordinate.longitude),
           let candidate = gcjToWgs(coordinate),
           isInMainland(latitude: candidate.latitude, longitude: candidate.longitude) {
            return candidate
        }
        return WGS84Coordinate(latitude: coordinate.latitude, longitude: coordinate.longitude)
    }

    private static func inBounds(latitude: Double, longitude: Double) -> Bool {
        (18.0...53.6).contains(latitude) && (73.4...135.1).contains(longitude)
    }

    private static func isExcludedRegion(latitude: Double, longitude: Double) -> Bool {
        contains(hongKong, latitude: latitude, longitude: longitude)
            || macao.contains { contains($0, latitude: latitude, longitude: longitude) }
            || taiwanAndIslands.contains { contains($0, latitude: latitude, longitude: longitude) }
    }

    private static func contains(_ polygon: Polygon, latitude: Double, longitude: Double) -> Bool {
        var previous = polygon[polygon.count - 1]
        var inside = false
        for point in polygon {
            if (point.lat > latitude) != (previous.lat > latitude),
               longitude < (previous.lon - point.lon) * (latitude - point.lat) / (previous.lat - point.lat) + point.lon {
                inside.toggle()
            }
            previous = point
        }
        return inside
    }

    static func gpsToMap(_ coordinate: WGS84Coordinate) -> CLLocationCoordinate2D {
        isInMainland(latitude: coordinate.latitude, longitude: coordinate.longitude) ? wgsToGcj(coordinate) : coordinate.clCoordinate
    }

    static func wgsToGcj(_ coordinate: WGS84Coordinate) -> CLLocationCoordinate2D {
        let delta = offset(at: coordinate.clCoordinate)
        return CLLocationCoordinate2D(latitude: coordinate.latitude + delta.lat, longitude: coordinate.longitude + delta.lon)
    }

    static func gcjToWgs(_ gcj: CLLocationCoordinate2D) -> WGS84Coordinate? {
        var estimate = gcj
        for _ in 0..<6 {
            let delta = offset(at: estimate)
            estimate = CLLocationCoordinate2D(latitude: gcj.latitude - delta.lat, longitude: gcj.longitude - delta.lon)
        }
        return WGS84Coordinate(latitude: estimate.latitude, longitude: estimate.longitude)
    }

    private static func offset(at c: CLLocationCoordinate2D) -> (lat: Double, lon: Double) {
        let a = 6378245.0, ee = 0.00669342162296594323
        let x = c.longitude - 105, y = c.latitude - 35
        let wave = (20 * sin(6 * x * .pi) + 20 * sin(2 * x * .pi)) * 2 / 3
        var lat = -100 + 2 * x + 3 * y + 0.2 * y * y + 0.1 * x * y + 0.2 * sqrt(abs(x)) + wave
        lat += (20 * sin(y * .pi) + 40 * sin(y / 3 * .pi)) * 2 / 3
        lat += (160 * sin(y / 12 * .pi) + 320 * sin(y * .pi / 30)) * 2 / 3
        var lon = 300 + x + 2 * y + 0.1 * x * x + 0.1 * x * y + 0.1 * sqrt(abs(x)) + wave
        lon += (20 * sin(x * .pi) + 40 * sin(x / 3 * .pi)) * 2 / 3
        lon += (150 * sin(x / 12 * .pi) + 300 * sin(x / 30 * .pi)) * 2 / 3
        let radians = c.latitude / 180 * .pi, sine = sin(radians)
        let magic = 1 - ee * sine * sine, root = sqrt(magic)
        return (lat * 180 / (a * (1 - ee) / (magic * root) * .pi), lon * 180 / (a / root * cos(radians) * .pi))
    }

